window.__PAGE_RUNTIME_PARTIALS__["partials/sb10-guia-05-preparar-mantenimiento-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\u003c!-- Generado por herramientas/generar_guias_mantenimiento.py (2026-10-22) desde el PDF original del\n     instructor (competencia 220501001, RAP 01). No editar a mano: editar mant_specs.py y regenerar. --\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 5 - Preparar el mantenimiento de equipos de cómputo\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha u-hidden\" id=\"sb-ficha-ok\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#materiales\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128193;\u003c/span\u003e Materiales de apoyo\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"santa-barbara-10a-guia-05-preparar-mantenimiento.html\" data-current-file=\"santa-barbara-10a-guia-05-preparar-mantenimiento.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128295;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 5\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003ePreparar mantenimiento | 10A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 5 - Preparar el mantenimiento de equipos de cómputo\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e80 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara | Grado 10\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 5 | Fase: Planeación\u003c/div\u003e\n        \u003ch1\u003ePreparar el mantenimiento de los equipos de cómputo de acuerdo con procedimientos técnicos y administrativos.\u003c/h1\u003e\n        \u003cp\u003eEn esta guía aprenderás a diferenciar el mantenimiento preventivo del correctivo, a interpretar manuales técnicos de fabricante, a reconocer herramientas, materiales y elementos de protección personal, y a preparar un plan de trabajo antes de intervenir un equipo real.\u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Mantener equipos de c\u0026oacute;mputo\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 80 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetización Digital, Asesoría Técnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la Zona de Influencia del CIAS.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003ePlaneación\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003ePlanificar procesos de intervención en alfabetización digital, asesoría técnica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501001 — Mantener equipos de cómputo según procedimiento técnico.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 01 \u0026mdash; Preparar el mantenimiento de los equipos de cómputo de acuerdo con procedimientos técnicos y administrativos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e80 horas (60 horas de formación directa y 20 horas de trabajo independiente)\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e¡Bienvenido, aprendiz! En el Magdalena Medio y el Occidente de Boyacá, ferreterías, misceláneas, droguerías y cooperativas agropecuarias dependen cada día más de sus computadores para facturar, llevar inventarios y comunicarse con proveedores. Sin embargo, muy pocas cuentan con un plan de mantenimiento: los equipos se intervienen solo cuando ya fallaron, casi siempre en el peor momento. Un técnico que sabe preparar el mantenimiento — diagnosticar antes de actuar, consultar los manuales correctos, alistar las herramientas adecuadas y documentar lo planeado — evita paradas de producción, alarga la vida útil de los equipos y protege la información del negocio.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eEn esta guía usted desarrollará el RAP 01 de la competencia «Mantener equipos de cómputo según procedimiento técnico»: aprenderá a diferenciar el mantenimiento preventivo del correctivo, a interpretar manuales técnicos de fabricante, a reconocer las herramientas, materiales, elementos de limpieza y de protección personal necesarios, y a preparar un plan de trabajo antes de intervenir un equipo real. El caso guía de esta guía es la \u003cstrong\u003eFerretería y Miscelánea Puerto Real\u003c/strong\u003e, un negocio familiar de Puerto Boyacá (Magdalena Medio) que nunca ha recibido mantenimiento programado en sus computadores. Usted será el técnico que la ayude a cambiar esa situación.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eTrabajará en cuatro momentos: primero reflexionará sobre el caso de Puerto Real; luego estudiará los conceptos clave de mantenimiento de equipos y practicará una inspección externa; después aplicará ese conocimiento diagnosticando un equipo real del taller y diligenciando su hoja de vida; y finalmente construirá, con ayuda de la herramienta HWMonitor, un Plan de Mantenimiento Preventivo y Correctivo completo, que sustentará ante el instructor.\u003c/p\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128737; Seguridad durante las prácticas, para cuidar a las personas y los equipos\u003c/div\u003e\n            \u003col class=\"u-steps-top\"\u003e\n          \u003cli\u003eTrabaje solo en los equipos que el instructor le asigne y con su permiso; no abra ningún equipo sin la autorización y supervisión del instructor.\u003c/li\u003e\n          \u003cli\u003eColóquese la pulsera antiestática antes de tocar un equipo y no use joyas metálicas ni tenga las manos húmedas.\u003c/li\u003e\n          \u003cli\u003eUse el alcohol isopropílico y el aire comprimido en un lugar ventilado, lejos del fuego y siguiendo las indicaciones del instructor.\u003c/li\u003e\n          \u003cli\u003eNo fuerce piezas ni desconecte cables que no haya identificado; si tiene dudas, pregunte antes de actuar.\u003c/li\u003e\n          \u003cli\u003eProteja los datos personales: no los muestre en fotos ni capturas de pantalla.\u003c/li\u003e\n          \u003cli\u003eReporte de inmediato al instructor cualquier ruido, olor, calentamiento o falla inesperada.\u003c/li\u003e\n            \u003c/ol\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box green u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003eComputador con suite ofimática (LibreOffice o Microsoft Office), acceso a internet, destornilladores de precisión, pulsera antiestática, soplador de aire comprimido y el formato de hoja de vida de equipos suministrado por el instructor. Algunas actividades son de trabajo directo con el instructor y otras de trabajo independiente. Lea siempre las instrucciones completas antes de empezar y guarde cada evidencia con un nombre descriptivo (por ejemplo, HojaVida_[TuNombre]_v1.0.pdf). \u003cstrong\u003eSin evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 · ACTIVIDADES DE REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 · Actividades de Reflexión Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes sobre el tema. Aquí no se evalúa el acierto, sino tu participación.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eActivar lo que usted ya sabe sobre mantenimiento de equipos y reconocer el costo de no planificarlo, antes de entrar a los conceptos técnicos. Metodología pedagógica: aprendizaje basado en problemas (ABP), con la técnica activa de lluvia de ideas en equipo. Todo el tiempo de reflexión es trabajo directo con el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexión Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 1 hora directa\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003e«Detectives del mantenimiento»: el caso de la Ferretería Puerto Real\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e En grupos de 3 o 4 personas, respondan mediante lluvia de ideas (no es necesario entregar producto escrito). Duración: 30 minutos directas.\u003c/p\u003e\n              \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Ferretería y Miscelánea Puerto Real, Puerto Boyacá (Magdalena Medio)\u003c/h3\u003e\n                \u003cp\u003eEste negocio familiar tiene 4 computadores: facturación, bodega, contabilidad y un punto de atención. Nunca han recibido mantenimiento programado. Esta semana, el computador de facturación se calienta demasiado, su ventilador suena fuerte y en ocasiones no reconoce la memoria USB del lector de código de barras.\u003c/p\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eLluvia de ideas en grupo (3 o 4 personas)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003cp class=\"intro-text u-note-0\"\u003eNo es necesario entregar un producto escrito por el grupo: registra aquí tus propias respuestas como participante de la discusión.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. ¿Qué síntomas del computador de facturación llaman su atención? Enumere al menos 3.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_311_sintomas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. ¿Qué posibles causas técnicas podrían explicar cada síntoma?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_311_causas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. ¿Qué herramientas o equipos de protección creen que necesitarán antes de abrir el computador?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_herramientas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. ¿Qué precauciones tomarían para no perder información ni dañar más el equipo?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_precauciones\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. ¿Alguna vez han visto un computador con síntomas parecidos en su casa, colegio o negocio familiar? ¿Qué pasó?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_experiencia\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"caso311DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCaso311\" class=\"btn-save-response\" onclick=\"actStd_save_caso311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_caso311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCaso311\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocialización en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Compartir el hallazgo más preocupante de cada grupo y cerrar con una idea final en la bitácora. Duración: 30 minutos directas.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eCada grupo comparte en máximo 2 minutos su síntoma más preocupante y la causa que consideran más probable.\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero los síntomas y agrupa las causas por tipo: mecánicas, eléctricas, de software o de falta de limpieza.\u003c/li\u003e\n                  \u003cli\u003eEscriba en su bitácora una idea final: ¿qué relación encuentra entre «no hacer mantenimiento preventivo» y «terminar haciendo mantenimiento correctivo urgente»?\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBitácora de cierre\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Síntoma más preocupante que compartió tu grupo y la causa más probable\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_312_sintoma_grupo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Idea final: ¿qué relación encuentra entre «no hacer mantenimiento preventivo» y «terminar haciendo mantenimiento correctivo urgente»?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_312_reflexion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"plenaria312DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 · CONTEXTUALIZACIÓN E IDENTIFICACIÓN DE CONOCIMIENTOS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 · Contextualización e Identificación de Conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los conceptos y la teoría que necesitas. Estúdialos con calma.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eConstruir la base conceptual sobre tipos de mantenimiento, manuales técnicos, materiales/herramientas y elementos de protección, y aplicarla en una primera inspección externa. Metodología pedagógica: aprendizaje colaborativo con estudio por bloques temáticos + demostración guiada.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualización\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 7 horas directas + 3 independientes (y 8 independientes de consulta sobre fallas)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de contenidos de mantenimiento de equipos (Bloques A y B)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Estudiar en equipo de 3 los 7 temas de los Bloques A y B y consolidar una tabla resumen en PDF: \u003ccode\u003eBloqueAB_RAP01_[TuNombre]_v1.0.pdf\u003c/code\u003e. Duración: 3 horas independientes + 4 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (3 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eEstudie los temas de los Bloques A y B usando los módulos de IT Essentials de Cisco Networking Academy (netacad.com) y los manuales técnicos que le indique el instructor. Tome apuntes en su bitácora. Llegue a clase con los conceptos básicos de mantenimiento preventivo, correctivo y elementos de protección revisados.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque A — Tipos y diagnóstico de mantenimiento)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eMantenimiento preventivo\u003c/td\u003e\u003ctd\u003eConcepto, periodicidad, ventajas y ejemplos aplicados a equipos de cómputo (limpieza interna, verificación de temperaturas, actualización de software).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eMantenimiento correctivo\u003c/td\u003e\u003ctd\u003eConcepto, diferencias con el preventivo, cuándo se aplica y riesgos de solo hacer mantenimiento correctivo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eDiagnóstico de equipos\u003c/td\u003e\u003ctd\u003eSíntomas comunes de falla física y lógica, y su relación con posibles causas (sobrecalentamiento, ruido, fallas de reconocimiento de dispositivos).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eManuales técnicos\u003c/td\u003e\u003ctd\u003eQué contienen (especificaciones, procedimientos de desarme, garantía) y cómo se consultan en el sitio del fabricante.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque B — Materiales, herramientas y protección personal)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eHerramientas de mantenimiento\u003c/td\u003e\u003ctd\u003eDestornilladores de precisión, pulsera antiestática, soplador de aire comprimido, brochas: función y uso correcto de cada una.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eElementos de limpieza y productos químicos\u003c/td\u003e\u003ctd\u003eAlcohol isopropílico, aire comprimido, limpia contactos: características, usos y precauciones de manejo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eElementos de protección personal (EPP)\u003c/td\u003e\u003ctd\u003ePulsera antiestática y su función para evitar descargas electrostáticas (ESD) que dañen componentes.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eForme un equipo de 3 personas. Repartan los 7 temas (4 del Bloque A + 3 del Bloque B): mínimo 2 temas por integrante.\u003c/li\u003e\n                  \u003cli\u003eDurante la primera hora, cada integrante explica sus temas al equipo (5 minutos por tema) mientras los demás completan sus apuntes.\u003c/li\u003e\n                  \u003cli\u003eEn LibreOffice Calc o Google Sheets, construyan una tabla de 3 columnas: «Tema», «¿Para qué sirve?», «Ejemplo aplicado en la Ferretería Puerto Real». Completen una fila por tema.\u003c/li\u003e\n                  \u003cli\u003eEl instructor realiza una plenaria de cierre donde cada equipo comparte su fila más importante.\u003c/li\u003e\n                  \u003cli\u003eExporten la tabla a PDF con el nombre \u003cstrong\u003eBloqueAB_RAP01_[TuNombre]_v1.0.pdf\u003c/strong\u003e y compártanla por el medio indicado por el instructor.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla resumen en PDF (BloqueAB_RAP01_[TuNombre]_v1.0.pdf) y apuntes previos en la bitácora. Esta actividad alimenta la Actividad 3.2.2. Al finalizar el estudio de contenidos, el instructor aplica de forma individual el cuestionario de conocimiento (instrumento IE-01).\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro guiado del aprendiz\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Reparto del equipo: temas y responsable de cada uno\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_321_reparto\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Temas que estudiaste tú (de los 7 distribuidos en tu equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_321_temas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Tema de tu fila en la tabla resumen\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g6mant_321_tema_fila\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. ¿Para qué sirve?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_321_paraque\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Ejemplo aplicado en la Ferretería Puerto Real\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_321_ejemplo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"bloqueAB321DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueAB321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueAB321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloqueAB321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueAB321\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-bloqueAB321\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEjercicio de inspección externa de equipos de cómputo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Inspeccionar externamente un equipo real del taller y diligenciar el formato de inspección suministrado por el instructor. Duración: 3 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (8 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eConsulte los recursos sobre diagnóstico de fallas de hardware y software recomendados por el instructor (módulos IT Essentials de Cisco Networking Academy y manuales técnicos de fabricantes). Elabore en su bitácora una tabla personal de «síntoma → posible causa → tipo de mantenimiento» con mínimo 8 casos.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipo de máximo 4 integrantes, reciban del instructor un equipo de cómputo del taller (sin abrirlo todavía).\u003c/li\u003e\n                  \u003cli\u003eAntes de empezar, organicen el puesto de trabajo (herramientas, pulsera antiestática, elementos de limpieza y un recipiente para residuos como polvo o empaques). Luego realicen una inspección puramente externa: estado físico de la carcasa, puertos, cables, ventilación, ruidos al encender y temperatura al tacto de la carcasa después de 10 minutos de uso (toque con cuidado y evite las partes metálicas calientes).\u003c/li\u003e\n                  \u003cli\u003eRegistren sus hallazgos en el \u003ca href=\"assets/materiales/guia6mant/Formato_Inspeccion_Externa_Equipos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eformato de inspección externa\u003c/a\u003e suministrado por el instructor, indicando para cada ítem si es normal o si requiere atención (ejemplo: ventilación libre de polvo = normal; ventilador con ruido fuerte = requiere atención).\u003c/li\u003e\n                  \u003cli\u003eRedacten un informe corto (máximo 1 página) con tres partes: qué observaron, qué concluyen (¿el equipo parece requerir mantenimiento preventivo, correctivo o ambos?) y por qué, con base en lo observado.\u003c/li\u003e\n                  \u003cli\u003eAdicionalmente, con base en el mismo equipo inspeccionado, diligencien la tabla de identificación de dispositivos de entrada, salida y almacenamiento: para cada categoría, indiquen el dispositivo específico que identificaron en el equipo, una definición breve y su ubicación física en el equipo.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eDocumento tipo informe con el formato de inspección externa diligenciado. Formato de entrega: PDF o DOCX. Medio de entrega: el indicado por el instructor. Tabla de identificación de dispositivos de entrada, salida y almacenamiento diligenciada.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eInforme de inspección (registro del aprendiz)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Qué observaron: hallazgos de la inspección externa (carcasa, puertos, cables, ventilación, ruidos, temperatura al tacto)\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g6mant_322_hallazgos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Qué concluyen y por qué (máximo 1 página): ¿el equipo requiere mantenimiento preventivo, correctivo o ambos?\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g6mant_322_conclusion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Dispositivo(s) de entrada identificados: definición breve y ubicación física\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_entrada\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Dispositivo(s) de salida identificados: definición breve y ubicación física\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_salida\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Dispositivo(s) de almacenamiento identificados: definición breve y ubicación física\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_almacenamiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"inspeccion322DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarInspeccion322\" class=\"btn-save-response\" onclick=\"actStd_save_inspeccion322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_inspeccion322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusInspeccion322\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-inspeccion322\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 · ACTIVIDADES DE APROPIACIÓN DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 · Actividades de Apropiación del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e pones en práctica lo aprendido. La mayoría de las evidencias que debes entregar salen de esta fase.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eProfundizar en el diagnóstico técnico de equipos y en el diligenciamiento de la documentación de soporte (hoja de vida del equipo), aplicando criterio técnico frente a casos reales. Metodología pedagógica: estudio de caso + aprendizaje basado en problemas (ABP), con trabajo guiado por el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiación\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 24 horas directas + 8 independientes\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eConsulta y análisis guiado de fallas comunes\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Analizar dos reportes nuevos del caso con base en el Bloque C y la tabla síntoma–causa. Duración: 8 horas independientes + 12 horas directas.\u003c/p\u003e\n              \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Ferretería y Miscelánea Puerto Real: nuevos hallazgos\u003c/h3\u003e\n                \u003cp\u003eDespués de la inspección externa de la Actividad 3.2.2, el propietario les entrega dos reportes adicionales: (1) el equipo de facturación se reinicia solo cuando corre el software contable durante más de una hora; (2) el equipo de la bodega no reconoce la impresora de código de barras aunque el cable USB está conectado. El propietario pregunta si esto se soluciona con mantenimiento preventivo o si ya es correctivo.\u003c/p\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque C — Diagnóstico avanzado)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eFallas físicas frecuentes\u003c/td\u003e\u003ctd\u003eAcumulación de polvo, ventiladores obstruidos, conexiones sueltas, deterioro de pasta térmica, oxidación de contactos.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eFallas lógicas frecuentes\u003c/td\u003e\u003ctd\u003eSoftware desactualizado, fragmentación, malware, arranque lento, procesos que consumen recursos en exceso.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eRelación entre síntoma y causa\u003c/td\u003e\u003ctd\u003eCómo asociar un síntoma reportado por el usuario (ej. «el equipo se calienta y hace ruido») con posibles causas físicas o lógicas.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003ePriorización de intervención\u003c/td\u003e\u003ctd\u003eCriterios para decidir qué se atiende primero: riesgo para el equipo, impacto en la operación del negocio, complejidad de la solución.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipo de máximo 4 integrantes, analicen los dos reportes del caso usando su tabla de síntoma-causa como referencia.\u003c/li\u003e\n                  \u003cli\u003ePara cada reporte, determinen: tipo de mantenimiento requerido (preventivo, correctivo o ambos), posibles causas ordenadas de más a menos probable, y nivel de urgencia (alta, media, baja).\u003c/li\u003e\n                  \u003cli\u003eRedacten una recomendación técnica dirigida al propietario, en lenguaje claro y sin tecnicismos innecesarios, explicando qué se va a hacer y por qué.\u003c/li\u003e\n                  \u003cli\u003eSocialicen su análisis en plenaria; el instructor retroalimenta la pertinencia técnica de cada diagnóstico.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eDocumento de análisis técnico con diagnóstico, causas probables, nivel de urgencia y recomendación redactada para el propietario. Formato: DOCX o PDF.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eAnálisis técnico (registro del aprendiz)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Estudio del Bloque C: fallas físicas y lógicas, relación síntoma–causa y priorización\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_bloqueC\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Reporte 1 (se reinicia con el software contable): tipo de mantenimiento, causas probables y urgencia\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_reporte1\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Reporte 2 (no reconoce la impresora de código de barras): tipo de mantenimiento, causas probables y urgencia\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_reporte2\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Recomendación técnica para el propietario (lenguaje claro)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_recomendacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"analisis331DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarAnalisis331\" class=\"btn-save-response\" onclick=\"actStd_save_analisis331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_analisis331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusAnalisis331\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-analisis331\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eDiagnóstico técnico y diligenciamiento de hoja de vida del equipo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Diagnosticar un equipo real del taller y diligenciar su hoja de vida. Duración: 12 horas directas.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eReciban del instructor un equipo de cómputo distinto al usado en la Actividad 3.2.2, junto con el formato de hoja de vida de equipos.\u003c/li\u003e\n                  \u003cli\u003eRealicen un diagnóstico técnico completo, sin abrir el equipo: inspección externa, encendido y verificación de funcionamiento básico (el sistema operativo inicia, el teclado, el mouse y los puertos USB responden, y anotar ruidos y temperatura al tacto).\u003c/li\u003e\n                  \u003cli\u003eDiligencien la hoja de vida del equipo con todos los datos requeridos: identificación del equipo, especificaciones técnicas, historial de intervención (si aplica), diagnóstico actual y recomendación de mantenimiento. Si un dato no se puede obtener, escriban «No determinado»; no lo inventen.\u003c/li\u003e\n                  \u003cli\u003eEntreguen al instructor la hoja de vida diligenciada para revisión y retroalimentación individual.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eHoja de vida del equipo diligenciada en su totalidad, firmada por el equipo de trabajo. Formato: el suministrado por el instructor, en PDF.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eDiagnóstico y hoja de vida (registro del aprendiz)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Diagnóstico técnico completo (sin abrir el equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_332_diagnostico\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Hoja de vida — identificación del equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_332_hv_identificacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Hoja de vida — especificaciones técnicas e historial de intervención (si un dato no se puede obtener: «No determinado»)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_332_hv_especificaciones\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Hoja de vida — diagnóstico actual y recomendación de mantenimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_332_hv_recomendacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"diagnostico332DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDiagnostico332\" class=\"btn-save-response\" onclick=\"actStd_save_diagnostico332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_diagnostico332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDiagnostico332\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-diagnostico332\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 · ACTIVIDADES DE TRANSFERENCIA DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 · Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e aplicas todo lo aprendido en un producto final que sustentas.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eAplicar de manera integral lo aprendido, elaborando un plan de mantenimiento preventivo real para el equipo de cómputo de un negocio, con monitoreo técnico de parámetros y sustentación ante el instructor. Metodología pedagógica: aprendizaje basado en proyectos, con producto final evaluable.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 28 horas directas + 9 independientes\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eLaboratorio de monitoreo técnico con HWMonitor\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Registrar durante 3 días las temperaturas y la velocidad del ventilador de un equipo y consolidar conclusiones. Duración: 9 horas independientes + 12 horas directas.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003e\u003cstrong\u003eTrabajo independiente (9 horas):\u003c/strong\u003e instale en un equipo de cómputo (propio, del hogar o del taller, según indique el instructor) el software HWMonitor u otra herramienta de monitoreo equivalente autorizada por el instructor. HWMonitor es un programa gratuito que muestra temperaturas, velocidades de ventiladores y voltajes del equipo; descárguelo solo del \u003ca href=\"https://www.cpuid.com/softwares/hwmonitor.html\" target=\"_blank\" rel=\"noopener\"\u003esitio oficial de CPUID\u003c/a\u003e y revise el \u003ca href=\"assets/materiales/guia6mant/Anexo_Reporte_Ejemplo_HWMonitor.pdf\" target=\"_blank\" rel=\"noopener\"\u003ereporte de ejemplo\u003c/a\u003e del material de apoyo. Explore sus funciones: temperatura de CPU, velocidad de ventiladores, voltajes.\u003c/li\u003e\n                  \u003cli\u003eDurante 3 días, registre en una tabla (columnas: día, momento, temperatura de la CPU en °C y velocidad del ventilador en RPM) las lecturas en tres momentos: equipo recién encendido, después de 30 minutos de uso normal, y después de 30 minutos de uso exigente (por ejemplo, varios programas abiertos al tiempo, sin forzar el equipo).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eSesión directa (12 horas):\u003c/strong\u003e en equipo de trabajo, comparen sus registros individuales y discutan qué valores se consideran normales y cuáles indican posible sobrecalentamiento o falla de ventilación. Apóyense en las especificaciones técnicas del fabricante (por ejemplo, la temperatura máxima de la CPU): una lectura cercana a ese máximo de forma sostenida es una posible anomalía.\u003c/li\u003e\n                  \u003cli\u003eElaboren una tabla comparativa consolidada del equipo, con conclusiones sobre el estado térmico de los equipos monitoreados y recomendaciones de mantenimiento preventivo.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla de registros individuales (3 días) + tabla comparativa consolidada del equipo con conclusiones. Formato: hoja de cálculo (XLSX) exportada a PDF.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro del laboratorio de monitoreo\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Registros individuales de los 3 días (día, momento, temperatura de la CPU °C, ventilador RPM)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_341_registros\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Tabla comparativa consolidada del equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_341_comparativa\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Conclusiones sobre el estado térmico y recomendaciones de mantenimiento preventivo\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_341_conclusion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"hwmonitor341DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarHwmonitor341\" class=\"btn-save-response\" onclick=\"actStd_save_hwmonitor341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_hwmonitor341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusHwmonitor341\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-hwmonitor341\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.4.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003ePlan de Mantenimiento Preventivo y sustentación\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Elaborar y sustentar el Plan de Mantenimiento Preventivo de los 4 equipos del caso. Duración: 16 horas directas.\u003c/p\u003e\n              \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Ferretería y Miscelánea Puerto Real: cierre del proceso\u003c/h3\u003e\n                \u003cp\u003eCon base en todo lo trabajado (inspección externa, diagnóstico técnico, hojas de vida y monitoreo térmico), el propietario de la Ferretería Puerto Real les solicita formalmente un Plan de Mantenimiento Preventivo para sus 4 equipos de cómputo, que le permita anticiparse a fallas y planificar el gasto en mantenimiento durante el año.\u003c/p\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipo de máximo 4 integrantes, elaboren el Plan de Mantenimiento Preventivo para los 4 equipos del caso en una tabla con estas columnas: equipo, actividad a realizar en cada visita, frecuencia o fecha (cronograma anual), materiales y herramientas, elementos de protección personal y responsable.\u003c/li\u003e\n                  \u003cli\u003eAnexen al plan las hojas de vida diligenciadas en la Actividad 3.3.2 como soporte del estado inicial de los equipos.\u003c/li\u003e\n                  \u003cli\u003ePreparen una sustentación oral de máximo 10 minutos por equipo, explicando su plan con lenguaje sencillo, como si se lo presentaran directamente al propietario del negocio. Participan todos los integrantes.\u003c/li\u003e\n                  \u003cli\u003eSustenten ante el instructor y sus compañeros. El instructor evalúa dominio técnico, claridad de la propuesta y pertinencia de las recomendaciones frente al caso.\u003c/li\u003e\n                  \u003cli\u003eEntreguen el Plan de Mantenimiento Preventivo en formato digital final, incluyendo las hojas de vida como anexos.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003ePlan de Mantenimiento Preventivo completo (DOCX o PDF) con anexos de hojas de vida, y sustentación oral ante el instructor.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBorrador del Plan de Mantenimiento Preventivo\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Cronograma anual de intervenciones (4 equipos): frecuencia o fecha\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_342_cronograma\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Actividades a realizar en cada visita\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_342_actividades\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Materiales y herramientas necesarias\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_342_materiales\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Elementos de protección personal (EPP) requeridos\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_342_epp\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Responsable de cada actividad del plan\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_342_responsables\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"planMantenimiento342DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlanMantenimiento342\" class=\"btn-save-response\" onclick=\"actStd_save_planMantenimiento342()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_planMantenimiento342()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlanMantenimiento342\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-planMantenimiento342\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ MATERIALES DE APOYO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"materiales\" class=\"section-title\"\u003eMateriales de Apoyo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eConsulta aquí\u003c/strong\u003e los documentos de referencia y las herramientas que necesitas para las actividades de esta guía.\u003c/p\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-teal\"\u003e\u0026#128193;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDocumentos y herramientas\u003c/h3\u003e\n              \u003cp\u003eMaterial de apoyo suministrado por el instructor\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eMaterial\u003c/th\u003e\u003cth\u003eActividad\u003c/th\u003e\u003cth\u003eEnlace\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eFormato de Inspección Externa de Equipos\u003c/td\u003e\u003ctd\u003e3.2.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Formato_Inspeccion_Externa_Equipos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eGA-F-05 — Hoja de Vida de Equipos de Cómputo\u003c/td\u003e\u003ctd\u003e3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/GA-F-05-HV-de-Equipos-de-Computo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eF-GR-02 — Hoja de Vida de Equipos Tecnológicos\u003c/td\u003e\u003ctd\u003e3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/f-gr-02-hoja-de-vida-equipos-tecnologicos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eGT-FO-01 — Formato Hojas de Vida de Equipos (V03, Excel)\u003c/td\u003e\u003ctd\u003e3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/GT-FO-01-FORMATO-HOJAS-DE-VIDA-EQUIPOS-V03.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Excel\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eF-GA-146 — Ficha Técnica de Equipos de Cómputo (Excel)\u003c/td\u003e\u003ctd\u003e3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/f-ga-146-ficha-tecnica-equipos-de-computo.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Excel\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad «El Detective» (caso ampliado)\u003c/td\u003e\u003ctd\u003e3.1.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/1_Actividad_El_Detective.docx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Word\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eManual de usuario de HWMonitor\u003c/td\u003e\u003ctd\u003e3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/HWMonitor_Manual_Usuario.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eReporte de ejemplo con HWMonitor\u003c/td\u003e\u003ctd\u003e3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Anexo_Reporte_Ejemplo_HWMonitor.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eEjemplo de Plan de Mantenimiento\u003c/td\u003e\u003ctd\u003e3.4.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Plan_de_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eEjemplo de Programa de Mantenimiento (V1R3)\u003c/td\u003e\u003ctd\u003e3.4.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Programa_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eArquitectura de PC (referencia técnica)\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Arquitectura_PC.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eArquitectura de Laptops (referencia técnica)\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Arquitectura_Laptops.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eConexión M.2 y SATA (referencia técnica)\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Conexion_M2_y_SATA.docx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Word\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eManual de mantenimiento del computador\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Manual_Mantenimiento_del_Computador.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e«Mantenimiento preventivo y correctivo para PCs» (Gutiérrez, Peñafiel, Villarreal)\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Comunidad_Emagister_Mantenimiento_Preventivo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCapítulo 2 — Conocimiento del Hardware (componentes internos, reglas de seguridad y hoja de especificaciones)\u003c/td\u003e\u003ctd\u003e3.2.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Modulo_2_Referencia_Adicional.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128295; Software de monitoreo (Actividad 3.4.1)\u003c/div\u003e\n            \u003cp\u003eHWMonitor se instala directamente desde el sitio oficial del fabricante: \u003ca href=\"https://www.cpuid.com/softwares/hwmonitor.html\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e. Si no tienes acceso a internet en el equipo donde vas a monitorear, pídele al instructor el instalador en USB.\u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128194; Material de apoyo que entrega el instructor\u003c/div\u003e\n            \u003cp\u003eEstos documentos del material de apoyo de la gu\u0026iacute;a todav\u0026iacute;a no est\u0026aacute;n publicados en el portal. Sol\u0026iacute;citalos a tu instructor:\u003c/p\u003e\n            \u003cul class=\"u-steps-top\"\u003e\u003c/ul\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos tienen tu nombre y número de ficha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e3 evidencias: conocimiento, desempe\u0026ntilde;o y producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\u003cth\u003eEvidencias\u003c/th\u003e\u003cth\u003eCriterios\u003c/th\u003e\u003cth\u003eInstrumento\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.1 + 3.2.1 — Reflexión inicial y estudio de contenidos de mantenimiento (Actividades 3.1.1, 3.1.2, 3.2.1)\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eCONOCIMIENTO:\u003c/strong\u003e cuestionario sobre tipos de mantenimiento (preventivo y correctivo), herramientas de diagnóstico y normas de seguridad eléctrica.\u003c/td\u003e\n                  \u003ctd\u003eDetermina el tipo de mantenimiento de los equipos de cómputo de acuerdo con el procedimiento técnico establecido. Interpreta los manuales técnicos del fabricante de acuerdo con la labor a realizar.\u003c/td\u003e\n                  \u003ctd\u003eTécnica: formulación de preguntas. Instrumento: cuestionario de conocimiento (IE-01)\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.2.2 + 3.3.1 + 3.3.2 — Inspección externa, análisis de fallas y diagnóstico técnico con hoja de vida\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eDESEMPEÑO:\u003c/strong\u003e inspección y diagnóstico del estado físico y funcional de equipos de cómputo reales del taller, aplicando normas de seguridad.\u003c/td\u003e\n                  \u003ctd\u003eOrganiza el puesto de trabajo con los equipos, herramientas, materiales, elementos de protección, productos químicos y manejo de residuos de acuerdo con normatividad vigente.\u003c/td\u003e\n                  \u003ctd\u003eTécnica: observación directa en el puesto de trabajo. Instrumento: lista de chequeo de desempeño (IE-02)\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.4.1 + 3.4.2 — Laboratorio de monitoreo con HWMonitor y Plan de Mantenimiento Preventivo\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003ePRODUCTO:\u003c/strong\u003e hoja de vida del equipo diligenciada y plan de mantenimiento propuesto para los equipos inspeccionados.\u003c/td\u003e\n                  \u003ctd\u003eElabora plan de trabajo según requerimientos y condiciones administrativas.\u003c/td\u003e\n                  \u003ctd\u003eTécnica: valoración de producto. Instrumento: lista de chequeo de producto (IE-03)\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-orange\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave\u003c/h3\u003e\n              \u003cp\u003e13 t\u0026eacute;rminos t\u0026eacute;cnicos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eMantenimiento preventivo\u003c/dt\u003e\u003cdd\u003eConjunto de actividades programadas y realizadas de forma periódica sobre un equipo de cómputo con el fin de evitar fallas antes de que ocurran, prolongando su vida útil.\u003c/dd\u003e\n            \u003cdt\u003eMantenimiento correctivo\u003c/dt\u003e\u003cdd\u003eIntervención que se realiza sobre un equipo de cómputo después de que se ha presentado una falla, con el propósito de restablecer su funcionamiento normal.\u003c/dd\u003e\n            \u003cdt\u003eCRU (Customer Replaceable Unit)\u003c/dt\u003e\u003cdd\u003eComponente o unidad de un equipo de cómputo que puede ser reemplazada directamente por el usuario o técnico sin necesidad de intervención especializada del fabricante.\u003c/dd\u003e\n            \u003cdt\u003eEPP\u003c/dt\u003e\u003cdd\u003eElementos de Protección Personal: equipos o dispositivos que protegen al técnico de riesgos durante las labores de mantenimiento, como la pulsera antiestática.\u003c/dd\u003e\n            \u003cdt\u003eESD (Electrostatic Discharge)\u003c/dt\u003e\u003cdd\u003eDescarga electrostática que puede dañar componentes electrónicos sensibles si no se toman las precauciones adecuadas (uso de pulsera antiestática, superficies de trabajo aterrizadas).\u003c/dd\u003e\n            \u003cdt\u003eRAEE\u003c/dt\u003e\u003cdd\u003eResiduos de Aparatos Eléctricos y Electrónicos: desechos generados por equipos electrónicos en desuso, que requieren disposición especial según normatividad ambiental vigente.\u003c/dd\u003e\n            \u003cdt\u003eHoja de vida del equipo\u003c/dt\u003e\u003cdd\u003eDocumento técnico que registra la información completa de un equipo de cómputo: identificación, especificaciones, historial de intervenciones y estado actual.\u003c/dd\u003e\n            \u003cdt\u003eManual técnico\u003c/dt\u003e\u003cdd\u003eDocumento suministrado por el fabricante que contiene las especificaciones, procedimientos de uso, mantenimiento y garantía de un equipo o componente.\u003c/dd\u003e\n            \u003cdt\u003eDiagnóstico\u003c/dt\u003e\u003cdd\u003eProceso de identificar, mediante observación y pruebas, el estado de un equipo y las posibles causas de una falla.\u003c/dd\u003e\n            \u003cdt\u003eBitácora\u003c/dt\u003e\u003cdd\u003eCuaderno o documento donde el aprendiz anota apuntes, datos y observaciones de su trabajo.\u003c/dd\u003e\n            \u003cdt\u003eHWMonitor\u003c/dt\u003e\u003cdd\u003ePrograma gratuito que muestra las temperaturas, las velocidades de los ventiladores y los voltajes de un equipo.\u003c/dd\u003e\n            \u003cdt\u003eSobrecalentamiento\u003c/dt\u003e\u003cdd\u003eTemperatura de un componente superior a la recomendada por el fabricante, que puede causar lentitud, reinicios o daños.\u003c/dd\u003e\n            \u003cdt\u003eEvidencia\u003c/dt\u003e\u003cdd\u003eProducto verificable del trabajo del aprendiz (captura, tabla, formato o informe) con nombre descriptivo y fecha.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-purple\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e6 referencias para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list u-refs\"\u003e\n            \u003cli\u003eCisco Networking Academy. \u003cem\u003eIT Essentials: PC Hardware and Software (v8.0)\u003c/em\u003e. \u003ca href=\"https://www.netacad.com\" target=\"_blank\" rel=\"noopener\"\u003enetacad.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eDiseño Curricular Técnico en Sistemas Teleinformáticos\u003c/em\u003e, versión 233108. SENA, Regional Boyacá.\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eBiblioteca Virtual SENA\u003c/em\u003e. \u003ca href=\"https://biblioteca.sena.edu.co\" target=\"_blank\" rel=\"noopener\"\u003ebiblioteca.sena.edu.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinisterio de Ambiente y Desarrollo Sostenible. \u003cem\u003eResolución 1297 de 2010\u003c/em\u003e y \u003cem\u003eDecreto 284 de 2018\u003c/em\u003e sobre gestión de Residuos de Aparatos Eléctricos y Electrónicos (RAEE). Colombia. \u003ca href=\"assets/materiales/guia6mant/resolucion-1297-de-2010.pdf\" target=\"_blank\" rel=\"noopener\"\u003eResolución 1297/2010 (PDF)\u003c/a\u003e · \u003ca href=\"assets/materiales/guia6mant/Decreto_284_de_2018.pdf\" target=\"_blank\" rel=\"noopener\"\u003eDecreto 284/2018 (PDF)\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMueller, S. (2021). \u003cem\u003eUpgrading and Repairing PCs\u003c/em\u003e (23rd ed.). Que Publishing.\u003c/li\u003e\n            \u003cli\u003eCPUID. \u003cem\u003eHWMonitor\u003c/em\u003e — Manual de usuario del software de monitoreo de hardware. \u003ca href=\"https://www.cpuid.com\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
